SELECT first_name, last_name, email_address
FROM Owners
WHERE state LIKE '%North%';

SELECT first_name, last_name, em_adr AS email
FROM Owners
WHERE state LIKE '%North%';

SELECT first_name || ' ' || last_name AS full_name
FROM players
ORDER BY birth_date;

SELECT DISTINCT t.Template_Details
FROM Templates AS t
JOIN Documents AS d ON d.tpl_id = t.Template_ID;

SELECT DISTINCT s.Fname, s.Age
FROM Student AS s
JOIN Has_Pet AS hp ON s.StuID = hp.StuID;

SELECT DISTINCT s.forename, s.Age
FROM Student AS s
JOIN Has_Pet AS hp ON hp.StuID = s.information;

SELECT AVG("LifeExpectancy") AS average_life_expectancy
FROM "country"
WHERE "Region" = 'Central Africa';

SELECT AVG("LifeExpectancy") AS average_life_expectancy
FROM "country"
WHERE "Region" = 'Southern and Central Asia';

SELECT SUM("Population") AS total_population, AVG("SurfaceArea") AS average_area
FROM "country"
WHERE "mainland" = 'North America' AND "SurfaceArea" > 3000;

SELECT Template_ID
FROM Templates
WHERE Template_Type_Code IN ('PP', 'PPT');

SELECT Template_ID
FROM Templates
WHERE Template_Type_Code IN ('PP', 'PPT');

SELECT "Location", "Name"
FROM "stadium"
WHERE "Capacity" BETWEEN 5000 AND 10000;

SELECT "Name", "Location"
FROM "stadium"
WHERE "Capacity" BETWEEN 5000 AND 10000;

SELECT tc.series_name, tc.Country
FROM TV_Channel AS tc
WHERE EXISTS (
    SELECT 1 FROM Cartoon AS c
    WHERE c.Channel = tc.id AND c.Directed_by = 'Ben Jones'
)
AND EXISTS (
    SELECT 1 FROM Cartoon AS c
    WHERE c.Channel = tc.id AND c.Directed_by = 'Michael Chang'
);

SELECT Song_Name
FROM singer
WHERE Age > (SELECT AVG(Age) FROM singer);

SELECT AVG(CAST(age AS REAL)) AS average_age
FROM Dogs
WHERE dog_id IN (SELECT dog_id FROM Treatments);

SELECT AVG(GNP) AS mean_gnp, SUM(Population) AS total_population
FROM country
WHERE GovernmentForm = 'US Territory';

SELECT AVG(GNP) AS average_gnp, SUM(Population) AS total_population
FROM country
WHERE GovernmentForm IN ('US Territory', 'US Commonwealth', 'Commonwealth of the US', 'Dependent Territory of the US');

SELECT AVG(LifeExpectancy) AS average_life_expectancy
FROM country
WHERE Region = 'Central Africa';
